import{z as o,x as n,o as e,c as s,q as t,j as B,D as a,d as l,s as r,S as i}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"数据配比的最终决定","description":"","frontmatter":{"title":"数据配比的最终决定","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pf2-data-mix-final.md","filePath":"llm/pf2-data-mix-final.md","lastUpdated":1791413859000}'),p={name:"llm/pf2-data-mix-final.md"};function d(D,E,m,C,h,_){const A=n("Mermaid");return e(),s("div",null,[E[2]||(E[2]=t('<h1 id="数据配比的最终决定" tabindex="-1">数据配比的最终决定 <a class="header-anchor" href="#数据配比的最终决定" aria-label="Permalink to &quot;数据配比的最终决定&quot;">​</a></h1><div class="epigraph"><p>配比不是「各来一点」，而是把每一枚训练 token 的梯度预算在桶之间做分配；它是数据侧的一阶决策。</p><footer>—— 据 Xie et al., DoReMi, NeurIPS 2023 与 Gopher / Llama 的来源配比实践整理</footer></div><p><a href="/llm/pf2-pretrain-checklist">上一课</a>把数据冻结写成开工判据，要求先洗后比、按真实 token 记账。本课补上那张清单里最重的一项怎么定：配比的最终决定。配比怎么求、谁说了算、定稿的文书长什么样——这是<a href="/llm/data-mixture-laws">领域配比</a>与 DoReMi 那些课的工程落点；本课不重讲 group DRO 的机制，只写最终决定在开工时刻如何拍板。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>配比的困难不在没有方法，而在<strong>没有终点</strong>：网页、代码、数学、多语言、百科，每类都能讲出扩张的理由，消融的空间是连续的，而点火是一次性的。没有终点的决策会退化成两种失败：一种永远在扫配比，预算耗在五十亿 token 的代理上却迟迟不开工；另一种凭直觉拍一组数，之后所有曲线异常都先怀疑配比，配方失去辩护能力。最终决定要回答的是：用哪个流程产出权重、用什么证据接受它、定稿后谁还允许动它。</p><p><span class="marginnote">「帕累托面」就是「不能再白拿的边界」：不牺牲任何一项就没法再改进另一项的那些组合。给代码加权重多半要压网页，探针裁决就是在边界上挑一个点——并且声明牺牲的是谁。</span></p><h3 id="从证据到定稿" tabindex="-1">从证据到定稿 <a class="header-anchor" href="#从证据到定稿" aria-label="Permalink to &quot;从证据到定稿&quot;">​</a></h3><p>定稿走三步。第一步，<strong>定桶</strong>：桶的分辨率决定 \\(w\\) 的含义——「网页」是一个桶还是拆成教育价值分级，直接改写权重向量；桶标签要在清洗后的数据上打，与<a href="/llm/data-quality-filter">质量过滤器</a>的档位同表。第二步，<strong>求初值</strong>：用小代理模型上的优化流程，如 <a href="/llm/doremi">DoReMi</a> 的 group DRO，得到一组照顾最差桶的权重 \\(w\\)；这组数是初值，不是答案。第三步，<strong>探针裁决</strong>：用下游探针（数学、代码、多语言、阅读）检查帕累托面，允许牺牲一点网页验证损失换取目标能力；显式声明哪一桶是付账方。</p>',8)),(e(),B(i,null,{default:a(()=>[r(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%AE%9A%E6%A1%B6%EF%BC%9A%E5%88%86%E8%BE%A8%E7%8E%87%E4%B8%8E%E6%A0%87%E7%AD%BE%22%5D%20--%3E%20B%5B%22%E5%B0%8F%E4%BB%A3%E7%90%86%E6%B1%82%E5%88%9D%E5%80%BC%20w%22%5D%0A%20%20B%20--%3E%20C%5B%22%E4%B8%8B%E6%B8%B8%E6%8E%A2%E9%92%88%E7%9C%8B%E5%B8%95%E7%B4%AF%E6%89%98%22%5D%0A%20%20C%20--%3E%7C%E6%9F%90%E6%A1%B6%E5%A1%8C%E4%BA%86%7C%20B%0A%20%20C%20--%3E%7C%E8%BE%BE%E6%A0%87%7C%20D%5B%22%E5%AE%9A%E7%A8%BF%EF%BC%9A%E6%9D%83%E9%87%8D%E8%A1%A8%20%2B%20%E8%AF%81%E6%8D%AE%E9%93%BE%20%2B%20%E7%89%88%E6%9C%AC%E5%8F%B7%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定稿文书要能被复述：各桶权重 \\(w_i\\) 按清洗后 token 计、合计为一；每桶的来源、清洗档位与指纹；初值来自哪次代理运行（配置哈希可查）；探针分数表与接受理由。配比与预算联动：总 token 数 \\(D\\) 定了，每个桶的绝对 token 数 \\(w_i D\\) 才落地——只写百分比不写绝对量，会让「数据够不够」在后课的数据耗尽判断里无法回答。定稿之后配比进入冻结区：训练中改配比不是本课的操作，那是数据耗尽与退火两课的例外通道，都要走显式升版。</p><p><span class="marginnote">DoReMi 的做法是在 280M 量级的代理上求权重，然后直接用到十倍以上的大模型上仍有效——但「小模型求权重」担保的只是权重，不是每个桶的最优 token 数；后者随规模移动，别把两件事并成一步。</span></p><p><span class="marginnote">数字实例：总预算 \\(D=2T\\) token、代码桶 \\(w_i=15\\%\\)，落地就是 \\(0.15\\times 2T=300B\\) 代码 token——冻结前要确认桶里真有这么多清洗后的独特数据，否则配比只是纸面数字。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么配比是采样测度上的一阶决策：交叉熵的期望按采样测度加权，\\(w\\) 直接决定每个桶分到多少梯度预算，比学习率、日程这些二阶旋钮的作用更靠前。为什么初值与终值要分开：DRO 的目标是补最差桶，它对「上游给多少」不敏感也不负责；探针裁决补的是方向性——你要的下游能力在哪条权衡线上。为什么定稿要带证据链：训练三个月后没有人记得当时为什么给代码 15% 而不是 12%；证据链让后课的每一次异常归因能先排除或确认配比，而不是重新猜一遍。</p><p><span class="marginnote">常见误区：初学者容易以为配比优化在找「唯一正确的比例」。实际上它是在一条权衡线上选点：多给代码必然少给网页，没有全都要；所以证据链必须记录「为什么选这个点」，而不只是这个点本身。</span></p>',7)),(e(),B(i,null,{default:a(()=>[r(A,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%B1%82%E9%85%8D%E6%AF%94%E7%9A%84%E4%B8%A4%E4%B8%AA%E9%98%B6%E6%AE%B5%EF%BC%9A%E5%90%84%E7%AD%94%E4%B8%80%E4%B8%AA%E9%97%AE%E9%A2%98%22%5D%20--%3E%20B%5B%22%E9%98%B6%E6%AE%B5%E4%B8%80%EF%BC%9ADRO%20%E5%88%9D%E5%80%BC%20w%22%5D%0A%20%20A%20--%3E%20C%5B%22%E9%98%B6%E6%AE%B5%E4%BA%8C%EF%BC%9A%E6%8E%A2%E9%92%88%E8%A3%81%E5%86%B3%22%5D%0A%20%20B%20--%3E%20B1%5B%22%E9%97%AE%EF%BC%9A%E6%9C%80%E5%B7%AE%E6%A1%B6%E4%BC%9A%E4%B8%8D%E4%BC%9A%E5%A1%8C%EF%BC%9F%22%5D%0A%20%20B1%20--%3E%20B2%5B%22%E4%BA%A7%E5%87%BA%EF%BC%9A%E7%85%A7%E9%A1%BE%E6%9C%80%E5%B7%AE%E6%A1%B6%E7%9A%84%E6%9D%83%E9%87%8D%EF%BC%8C%E5%8F%AF%E8%B7%A8%E8%A7%84%E6%A8%A1%E8%BF%81%E7%A7%BB%22%5D%0A%20%20C%20--%3E%20C1%5B%22%E9%97%AE%EF%BC%9A%E8%A6%81%E7%9A%84%E4%B8%8B%E6%B8%B8%E8%83%BD%E5%8A%9B%E5%9C%A8%E5%93%AA%E6%9D%A1%E6%9D%83%E8%A1%A1%E7%BA%BF%E4%B8%8A%EF%BC%9F%22%5D%0A%20%20C1%20--%3E%20C2%5B%22%E4%BA%A7%E5%87%BA%EF%BC%9A%E6%8E%A5%E5%8F%97%E7%90%86%E7%94%B1%20%2B%20%E6%98%BE%E5%BC%8F%E4%BB%98%E8%B4%A6%E6%96%B9%22%5D%0A%20%20B2%20--%3E%20D%5B%22%E5%90%88%E6%88%90%E6%9C%80%E7%BB%88%20w%EF%BC%9A%E5%8F%AF%E8%BE%A9%E6%8A%A4%E3%80%81%E5%8F%AF%E5%BD%92%E5%9B%A0%22%5D%0A%20%20C2%20--%3E%20D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=t('<p>这张图回答的是「初值与终值为什么不能由一步包办」：DRO 只担保不塌，方向性要靠探针显式选择，两份产出合起来才是可辩护的定稿。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课定的是主干阶段的静态配比；退火期换高质量混合是另一根旋钮，见退火与数据课程一课。桶内怎么清洗、去重怎么配参数，是数据工程课的事，本课只消费它们的输出档位。合成数据作为独立桶进入 \\(w\\) 的口径、以及对占比的约束，见<a href="/llm/synthetic-pretrain">合成数据在预训练</a>的讨论。指令格式进预训练测度同样只是配比里的一个小桶加模板约束，见<a href="/llm/instruction-in-pretrain">指令进预训练</a>。最后，配比的最优值随模型规模与数据制度移动：这次定稿是这次点火的定稿，不是定理。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>配比是把梯度预算在桶之间分配，是数据侧的一阶决策，先洗后比、按真实 token 记账。</li><li>定稿三步：定桶、小代理求初值、探针裁决帕累托；声明付账方。</li><li>定稿文书含权重表、绝对 token 数、证据链与版本号；只写百分比不算定稿。</li><li>配比定稿进冻结区；中途改动只走数据耗尽与退火两条显式通道。</li><li>出处：Xie et al., DoReMi, NeurIPS 2023；Gopher / Llama 的来源配比实践；桶口径对照 Dolma / FineWeb（Soldaini et al.；Penedo et al.）。</li></ul>',5))])}const c=o(p,[["render",d]]);export{F as __pageData,c as default};
